protected TFMWorkflowsTable makeEntry(TFMWorkflowName _name)
{
    TFMWorkflowsTable                workflowTable;

    select firstonly workflowTable where workflowTable.WorkflowName == _name;

    if (workflowTable)
    {
        return workflowTable;
    }

    workflowTable.WorkflowName = _name;
    workflowTable.Description = _name;
    workflowTable.FastForwardMode = TFMWorkflowFastForwardMode::InputAndScanValues;
    workflowTable.IncludeHiddenStepsInSummary = NoYes::No;
    workflowTable.AutoSave = NoYes::No;
    workflowTable.PrefillExpectedValueOnLocationScan = NoYes::Yes;
    workflowTable.CancelBehaviour = TFMWorkflowCancelBehaviour::Close;
    workflowTable.ScanBehaviourWhenRegisteringQuantity = TFMWorkflowScanBehaviourWhenRegisteringQuantity::ScanNextItem;
    workflowTable.insert();

    return workflowTable;
}
